export type RevampMoneyKey = keyof typeof REVAMP_MONEY_COPY;
export function moneyText(locale: Locale | undefined, key: RevampMoneyKey, vars?: Record<string, string | number>): string {
  const row = REVAMP_MONEY_COPY[key];
  const text = locale === "tl" ? row[0] : locale === "id" ? row[1] : locale === "vi" ? row[2] : key;
  return vars ? text.replace(/\{(\w+)\}/g, (match, name: string) => name in vars ? String(vars[name]) : match) : text;
}

// RPC/backend details and user-entered names must not be guessed or rewritten.
export function moneyMessage(locale: Locale | undefined, message: string): string {
  return Object.prototype.hasOwnProperty.call(REVAMP_MONEY_COPY, message)
    ? moneyText(locale, message as RevampMoneyKey) : message;
}
export const moneyCopy = (locale: Locale | undefined) => (key: RevampMoneyKey, vars?: Record<string, string | number>) => moneyText(locale, key, vars);
